#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_INCOMING FW_OUTGOING FW_INCOMING_WAN_DMZ FW_PORTFORWARDING; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_IP fws_Block_Bad_dst && fail 'an IP group named fws_Block_Bad_dst exists; nothing was written'
named FW_GROUP_IP fws_Admins.1.alm && fail 'an IP group named fws_Admins.1.alm exists; nothing was written'
named FW_GROUP_PORT fws_Web_Out && fail 'a port group named fws_Web_Out exists; nothing was written'
named FW_GROUP_IP fws_Update-Site.1.alm && fail 'an IP group named fws_Update-Site.1.alm exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Block_Bad_dst --set .COMMENT 'FWShift: Bad-Nets.1.alm, Bad-Nets.2.alm'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.0.2.66
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.0/25
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Admins.1.alm --set .COMMENT 'FWShift: Admins.1.alm'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.5.10-10.10.5.20
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Update-Site.1.alm --set .COMMENT 'FWShift: Update-Site.1.alm'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP updates.example.com
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_Web_Out --set .COMMENT 'FWShift: Web Out'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8000-8010
N=$((N+1))

# FW_INCOMING
N=$(rows FW_INCOMING)
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 198.51.100.10 --set .IN_PORT 443 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'Web In'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 198.51.100.11 --set .IN_PORT 25 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'Mail In'
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 22 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'Admin SSH'
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_Admins.1.alm
N=$((N+1))

# FW_INCOMING_WAN_DMZ
N=$(rows FW_INCOMING_WAN_DMZ)
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 198.51.100.10 --set .IN_PORT 443 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'Web In'
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 198.51.100.11 --set .IN_PORT 25 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'Mail In'
N=$((N+1))

# FW_PORTFORWARDING
N=$(rows FW_PORTFORWARDING)
gc --silent --goto FW_PORTFORWARDING --add-row --set .PROTO tcp --set .SRC_IP 0.0.0.0/0 --set .SRC_PORT any --set .IN_IP 198.51.100.10 --set .IN_PORT 443 --set .OUT_IP 10.20.0.10 --set .OUT_PORT 443 --set .LOG no --set .COMMENT 'Web-Public (Web In): static NAT action Web-Public of policy Web In'
N=$((N+1))
gc --goto FW_PORTFORWARDING --add-row --set .PROTO tcp --set .SRC_IP 0.0.0.0/0 --set .SRC_PORT any --set .IN_IP 198.51.100.11 --set .IN_PORT 25 --set .OUT_IP 10.20.0.25 --set .OUT_PORT 2525 --set .LOG no --set .COMMENT 'Mail-Public (Mail In): static NAT action Mail-Public of policy Mail In'
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
